services:
  heyheybot:
    build:
      context: .
      dockerfile: Dockerfile
    image: heyheybot:latest
    container_name: HeyHeyBot
    environment:
      - DISCORD_TOKEN=[REDACTED]}
      - DISCORD_CONTINUE_PRESENCE=${DISCORD_CONTINUE_PRESENCE:-True}
      - DISCORD_ARRIVAL_ANNOUNCE=${DISCORD_ARRIVAL_ANNOUNCE:-True}
      - DISCORD_LEAVE_ANNOUNCE=${DISCORD_LEAVE_ANNOUNCE:-True}
      - DISCORD_MUTING_ANNOUNCE=${DISCORD_MUTING_ANNOUNCE:-False}
      - DISCORD_ANNOUNCE_COOLDOWN=${DISCORD_ANNOUNCE_COOLDOWN:-5}
      - DISCORD_VOLUME=${DISCORD_VOLUME:-1.0}
      - DISCORD_LOGLEVEL=${DISCORD_LOGLEVEL:-WARNING}
      - WEBPAGE_USERNAME=${WEBPAGE_USERNAME}
      - WEBPAGE_PASSWORD=[REDACTED]}
      # Must be 0.0.0.0 for the published port below to be reachable
      - WEBPAGE_HOST=${WEBPAGE_HOST:-0.0.0.0}
      - WEBPAGE_PORT=${WEBPAGE_PORT:-5100}
      # Keeps web sessions alive across restarts (optional)
      - SECRET_KEY=${SECRET_KEY:-}
      # Optional proxy for the Discord API/gateway: http://... or socks5://...
      # Voice traffic is UDP and does NOT go through the proxy.
      - PROXY_URL=${PROXY_URL:-}
      - PROXY_USERNAME=${PROXY_USERNAME:-}
      - PROXY_PASSWORD=[REDACTED]}
      # - SSL_CERT=${SSL_CERT:-/app/certs/fullchain.pem}
      # - SSL_KEY=${SSL_KEY:-/app/certs/privkey.pem}
    volumes:
      - ./data:/app/data
      - ./logs:/app/logs
      # For SSL certificates:
      # - ./certs:/app/certs
    ports:
      - ${WEBPAGE_PORT:-5100}:${WEBPAGE_PORT:-5100}
    healthcheck:
      test: ["CMD", "python3", "/app/healthcheck.py"]
      interval: 60s
      timeout: 10s
      start_period: 30s
      retries: 3
    restart: unless-stopped

'''
Integration tests for the web panel, covering the security and correctness
regressions found in review. Requires flask and ffmpeg.

Run with: python3 -m unittest discover -s tests
'''
import io
import os
import re
import shutil
import struct
import sys
import tempfile
import unittest
import wave

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))


def make_wav(seconds=0.3, rate=8000):
    buf = io.BytesIO()
    with wave.open(buf, 'wb') as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(rate)
        w.writeframes(struct.pack('<h', 1000) * int(rate * seconds))
    return buf.getvalue()


class WebAppTestCase(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        if shutil.which('ffmpeg') is None:
            raise unittest.SkipTest('ffmpeg is not installed')
        cls.sandbox = tempfile.mkdtemp(prefix='heyheybot-test-')
        os.environ.update(
            WEBPAGE_USERNAME='admin',
            WEBPAGE_PASSWORD='s3cret',
            DISCORD_LOGLEVEL='CRITICAL',
            UPLOAD_FOLDER=os.path.join(cls.sandbox, 'audio'),
            GREETINGS_FOLDER=os.path.join(cls.sandbox, 'greetings'),
        )
        import webserver
        cls.webserver = webserver

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.sandbox, ignore_errors=True)

    def setUp(self):
        self.app = self.webserver.WebApp()
        self.app.app.config['TESTING'] = True
        self.client = self.app.app.test_client()
        for folder in (self.app.upload_folder, self.app.greetings_folder):
            for name in os.listdir(folder):
                os.remove(os.path.join(folder, name))

    def csrf(self):
        response = self.client.get('/login')
        match = re.search(rb'name="csrf_token" value="([^"]+)"', response.data)
        self.assertIsNotNone(match, 'login.html must render a CSRF token')
        return match.group(1).decode()

    def login(self):
        response = self.client.post(
            '/login', data={'username': 'admin', 'password': 's3cret', 'csrf_token': self.csrf()}
        )
        self.assertEqual(response.status_code, 302)

    def upload(self, filename='sound.wav', content=None, **extra):
        data = {'file': (io.BytesIO(content or make_wav()), filename), 'csrf_token': self.csrf()}
        data.update(extra)
        return self.client.post('/upload', data=data, content_type='multipart/form-data')

    # --- auth ---------------------------------------------------------

    def test_browser_is_redirected_when_logged_out(self):
        self.assertEqual(self.client.get('/', headers={'Accept': 'text/html'}).status_code, 302)

    def test_api_returns_401_when_logged_out(self):
        self.assertEqual(self.client.get('/get_greetings').status_code, 401)

    def test_health_needs_no_auth(self):
        self.assertEqual(self.client.get('/health').status_code, 200)

    def test_post_without_csrf_is_rejected(self):
        response = self.client.post('/login', data={'username': 'admin', 'password': 's3cret'})
        self.assertEqual(response.status_code, 400)

    def test_bruteforce_is_locked_out(self):
        codes = []
        for _ in range(7):
            codes.append(self.client.post(
                '/login', data={'username': 'admin', 'password': 'wrong', 'csrf_token': self.csrf()}
            ).status_code)
        self.assertEqual(codes[-1], 429, codes)

    # --- uploads (A1, A2) ---------------------------------------------

    def test_wav_upload_is_not_truncated(self):
        # ffmpeg used to convert the file onto itself, producing an empty file.
        self.login()
        self.assertEqual(self.upload('Кот тест.wav').status_code, 200)
        files = os.listdir(self.app.upload_folder)
        self.assertEqual(files, ['Кот тест.wav'])
        self.assertGreater(os.path.getsize(os.path.join(self.app.upload_folder, files[0])), 1000)

    def test_broken_upload_is_reported_and_cleaned_up(self):
        self.login()
        response = self.upload('bad.mp3', content=b'this is not audio')
        self.assertEqual(response.status_code, 400)
        self.assertEqual(os.listdir(self.app.upload_folder), [])

    def test_missing_file_does_not_crash_the_template(self):
        self.login()
        response = self.client.post('/upload', data={'csrf_token': self.csrf()},
                                    content_type='multipart/form-data')
        self.assertEqual(response.status_code, 400)
        self.assertIn(b'No file selected', response.data)

    # --- path traversal (A3) ------------------------------------------

    def test_delete_rejects_traversal(self):
        self.login()
        victim = os.path.join(self.sandbox, 'victim.txt')
        with open(victim, 'w') as handle:
            handle.write('keep me')
        response = self.client.post('/delete', json={
            'filename': '../victim.txt', 'folder': 'soundboard', 'csrf_token': self.csrf()
        })
        self.assertEqual(response.status_code, 400)
        self.assertTrue(os.path.exists(victim))

    def test_delete_is_not_reachable_over_get(self):
        self.login()
        self.assertEqual(self.client.get('/delete?filename=x.wav').status_code, 405)

    def test_set_greeting_rejects_traversal(self):
        self.login()
        response = self.client.post('/set_greeting', json={
            'username': 'bob', 'filename': '../../app.py', 'csrf_token': self.csrf()
        })
        self.assertEqual(response.status_code, 400)

    def test_set_version_rejects_non_numeric_version(self):
        self.login()
        response = self.client.post('/set_version_as_current', json={
            'username': 'bob', 'version': '../../etc/passwd', 'csrf_token': self.csrf()
        })
        self.assertEqual(response.status_code, 400)

    def test_normal_delete_works(self):
        self.login()
        self.upload('sound.wav')
        response = self.client.post('/delete', json={
            'filename': 'sound.wav', 'folder': 'soundboard', 'csrf_token': self.csrf()
        })
        self.assertEqual(response.status_code, 200)
        self.assertEqual(os.listdir(self.app.upload_folder), [])

    # --- greetings (A5) -----------------------------------------------

    def test_cyrillic_greeting_keeps_its_name_and_versions(self):
        self.login()
        for _ in range(2):
            response = self.client.post('/upload_greeting', data={
                'file': (io.BytesIO(make_wav()), 'g.wav'),
                'discord_username': 'Антон',
                'csrf_token': self.csrf(),
            }, content_type='multipart/form-data')
            self.assertEqual(response.status_code, 200)
        self.assertEqual(sorted(os.listdir(self.app.greetings_folder)), ['Антон.1.wav', 'Антон.wav'])

    def test_greeting_by_user_id(self):
        self.login()
        response = self.client.post('/upload_greeting', data={
            'file': (io.BytesIO(make_wav()), 'g.wav'),
            'discord_username': '123456789012345678',
            'csrf_token': self.csrf(),
        }, content_type='multipart/form-data')
        self.assertEqual(response.status_code, 200)
        self.assertIn('123456789012345678.wav', os.listdir(self.app.greetings_folder))

    def test_play_serves_uploaded_file(self):
        self.login()
        self.upload('sound.wav')
        response = self.client.get('/play?filename=sound.wav&folder=soundboard')
        self.assertEqual(response.status_code, 200)
        self.assertGreater(len(response.data), 1000)
        response.close()


class ReverseProxyTestCase(WebAppTestCase):
    """The panel behind Traefik/nginx: TRUSTED_PROXIES makes X-Forwarded-* count."""

    def setUp(self):
        os.environ['TRUSTED_PROXIES'] = '1'
        super().setUp()

    def tearDown(self):
        os.environ.pop('TRUSTED_PROXIES', None)

    def proxied_login(self, client, real_ip, password='wrong'):
        return client.post(
            '/login',
            data={'username': 'admin', 'password': password, 'csrf_token': self.csrf()},
            headers={'X-Forwarded-For': real_ip, 'X-Forwarded-Proto': 'https'},
            environ_overrides={'REMOTE_ADDR': '172.18.0.2'},
        )

    def test_lockout_is_per_client_not_per_proxy(self):
        # Without ProxyFix every request looks like it comes from the proxy, so one
        # attacker would lock out everybody.
        attacker = self.app.app.test_client()
        self.client = attacker
        codes = [self.proxied_login(attacker, '203.0.113.9').status_code for _ in range(7)]
        self.assertEqual(codes[-1], 429, codes)

        victim = self.app.app.test_client()
        self.client = victim
        self.assertEqual(self.proxied_login(victim, '198.51.100.5').status_code, 401)

    def test_session_cookie_is_secure_behind_a_proxy(self):
        self.assertTrue(self.app.app.config['SESSION_COOKIE_SECURE'])


if __name__ == '__main__':
    unittest.main()

'''
Tests for the shared helpers. Run with: python3 -m unittest discover -s tests
'''
import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import utils


class SanitizeTests(unittest.TestCase):
    def test_keeps_non_ascii_names(self):
        # werkzeug's secure_filename turns this into 'wav', which broke every
        # Cyrillic greeting.
        self.assertEqual(utils.sanitize_filename('Антон.wav'), 'Антон.wav')
        self.assertEqual(utils.sanitize_filename('日本語.wav'), '日本語.wav')

    def test_keeps_spaces_and_inner_dots(self):
        self.assertEqual(utils.sanitize_filename('Anton Ivanov.wav'), 'Anton Ivanov.wav')
        self.assertEqual(utils.sanitize_filename('user.2.wav'), 'user.2.wav')

    def test_rejects_empty_results(self):
        for bad in ('', '.', '..', '....', '.wav', '   '):
            with self.assertRaises(ValueError, msg=bad):
                utils.sanitize_filename(bad)

    def test_rejects_non_strings(self):
        for bad in (None, 5, [], {}):
            with self.assertRaises(ValueError):
                utils.sanitize_filename(bad)

    def test_strips_control_characters(self):
        self.assertEqual(utils.sanitize_filename('a\x01b.wav'), 'ab.wav')

    def test_extension_is_normalized(self):
        self.assertEqual(utils.sanitize_filename('song.WAV'), 'song.wav')
        self.assertEqual(utils.sanitize_filename('song'), 'song.wav')

    def test_length_is_capped(self):
        self.assertLessEqual(len(utils.sanitize_component('x' * 500)), utils.MAX_COMPONENT_LENGTH)


class SafePathTests(unittest.TestCase):
    def test_rejects_traversal(self):
        for bad in ('../../app.py', '..\\..\\app.py', 'a/b.wav', '/etc/passwd', 'x\x00.wav'):
            with self.assertRaises(ValueError, msg=bad):
                utils.safe_path(utils.AUDIO_DIR, bad)

    def test_accepts_normal_names(self):
        path = utils.safe_path(utils.AUDIO_DIR, 'Кот.wav')
        self.assertTrue(path.endswith('Кот.wav'))
        self.assertTrue(path.startswith(os.path.realpath(utils.resolve(utils.AUDIO_DIR))))


class CheckValTests(unittest.TestCase):
    def test_truthy_values(self):
        for value in ('true', 'True', 'TRUE', '1', 'yes', 'on', ' y '):
            self.assertTrue(utils.check_val(value), value)

    def test_falsy_values(self):
        for value in ('false', '0', 'no', 'off', 'nonsense', ''):
            self.assertFalse(utils.check_val(value), value)

    def test_default_used_when_unset(self):
        self.assertTrue(utils.check_val(None, default=True))
        self.assertFalse(utils.check_val(None, default=False))

    def test_bools_pass_through(self):
        self.assertTrue(utils.check_val(True, default=False))


class EnvTests(unittest.TestCase):
    def setUp(self):
        for name in ('HHB_TEST_FLAG', 'HHB_TEST_ALIAS', 'HHB_TEST_INT'):
            os.environ.pop(name, None)

    tearDown = setUp

    def test_env_flag_prefers_first_name(self):
        os.environ['HHB_TEST_ALIAS'] = 'true'
        self.assertTrue(utils.env_flag(False, 'HHB_TEST_FLAG', 'HHB_TEST_ALIAS'))
        os.environ['HHB_TEST_FLAG'] = 'false'
        self.assertFalse(utils.env_flag(True, 'HHB_TEST_FLAG', 'HHB_TEST_ALIAS'))

    def test_env_int_survives_garbage(self):
        os.environ['HHB_TEST_INT'] = 'not a number'
        self.assertEqual(utils.env_int('HHB_TEST_INT', 5100), 5100)
        os.environ['HHB_TEST_INT'] = '8080'
        self.assertEqual(utils.env_int('HHB_TEST_INT', 5100), 8080)
        os.environ['HHB_TEST_INT'] = '99999'
        self.assertEqual(utils.env_int('HHB_TEST_INT', 5100, maximum=65535), 5100)


if __name__ == '__main__':
    unittest.main()
